    );

    await client.query('COMMIT');

    res.status(201).json({
      message: 'Recipe saved successfully',
      recipeId: recipeId,
      recipeName: recipeData.name
    });

  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Save recipe error:', error);
    res.status(500).json({ 
